61	class AWSLogger final : public Aws::Utils::Logging::LogSystemInterface
62	{
63	public:
64	    explicit AWSLogger(bool enable_s3_requests_logging_)
65	        :enable_s3_requests_logging(enable_s3_requests_logging_)
66	    {
67	        for (auto [tag, name] : S3_LOGGER_TAG_NAMES)
68	            tag_loggers[tag] = &Poco::Logger::get(name);
69	
70	        default_logger = tag_loggers[S3_LOGGER_TAG_NAMES[0][0]];
71	    }
72	
73	    ~AWSLogger() final = default;
74	
75	    Aws::Utils::Logging::LogLevel GetLogLevel() const final
76	    {
77	        if (enable_s3_requests_logging)
78	            return Aws::Utils::Logging::LogLevel::Trace;
79	        else
80	            return Aws::Utils::Logging::LogLevel::Info;
81	    }
82	
83	    void Log(Aws::Utils::Logging::LogLevel log_level, const char * tag, const char * format_str, ...) final // NOLINT
84	    {
85	        callLogImpl(log_level, tag, format_str); /// FIXME. Variadic arguments?
86	    }
87	
88	    void LogStream(Aws::Utils::Logging::LogLevel log_level, const char * tag, const Aws::OStringStream & message_stream) final
89	    {
90	        callLogImpl(log_level, tag, message_stream.str().c_str());
91	    }
92	
93	    void callLogImpl(Aws::Utils::Logging::LogLevel log_level, const char * tag, const char * message)
94	    {
95	        const auto & [level, prio] = convertLogLevel(log_level);
96	        if (tag_loggers.contains(tag))
97	        {
98	            LOG_IMPL(tag_loggers[tag], level, prio, "{}", message);
99	        }
100	        else
101	        {
102	            LOG_IMPL(default_logger, level, prio, "{}: {}", tag, message);
103	        }
104	    }
105	
106	    void Flush() final {}
107	
108	private:
109	    Poco::Logger * default_logger;
110	    bool enable_s3_requests_logging;
111	    std::unordered_map<String, Poco::Logger *> tag_loggers;
112	};
